// Let's fetch one of the dictionary pages using fetch in page context or fetch_url to see what data is on MW dictionary pages
const pageCheck = await browserjs(tabId, async () => {
  const wordsToTest = ["astronaut", "apricot", "afterthought", "kilowatt", "juggernaut", "overwrought"];
  const results = {};
  for (const w of wordsToTest) {
    try {
      const resp = await fetch(`https://www.merriam-webster.com/dictionary/${w}`);
      const text = await resp.text();
      // Check if text contains "Popularity" or "frequency" or "Top "
      const parser = new DOMParser();
      const doc = parser.parseFromString(text, "text/html");

      // Look for popularity elements
      const popEl = doc.querySelector('.word-popularity, [class*="popularity"], [class*="frequency"], [class*="rank"]');

      // Check for any text matching "Top X% of words" or "Bottom X% of words"
      const match = text.match(/Top\s+\d+%\s+of\s+words|Bottom\s+\d+%\s+of\s+words/i);

      // Check for mwdata in the page
      const mwdataMatch = text.match(/window\.mwdata\s*=\s*({.*?});/s);

      results[w] = {
        popEl: popEl ? popEl.textContent.trim() : null,
        popMatch: match ? match[0] : null,
        status: resp.status
      };
    } catch (e) {
      results[w] = { error: e.message };
    }
  }
  return results;
});

