  const withFreq = threeSyllables.map(item => {
    const fTag = item.tags?.find(t => t.startsWith('f:'));
    const freq = fTag ? parseFloat(fTag.slice(2)) : 0;
    return {
      word: item.word,
      freq,
      score: item.score
    };
  });

  // Sort descending by frequency
  withFreq.sort((a, b) => b.freq - a.freq);

  return {
    total3Syllable: withFreq.length,
    top20ByFreq: withFreq.slice(0, 20),
    top20ByScore: [...withFreq].sort((a, b) => b.score - a.score).slice(0, 20)
