const tabId = 583778164;

const syllableData = await browserjs(tabId, () => {
  // Find the H3 for "3 syllables"
  const h3s = Array.from(document.querySelectorAll('h3'));
  const targetH3 = h3s.find(h => h.textContent.trim().toLowerCase().includes('3 syllable'));
  if (!targetH3) return { error: "No 3 syllables heading found" };

  // Let's get the container or siblings following targetH3
  let current = targetH3.nextElementSibling;
  const elements = [];
  while (current && current.tagName !== 'H3') {
    elements.push(current);
    current = current.nextElementSibling;
  }

  // Also check all links/spans inside those elements or the section
  const words = [];
  for (const el of elements) {
    const wordEls = el.querySelectorAll('a, span.word, .rhyme-item, li');
    if (wordEls.length > 0) {
      wordEls.forEach(w => {
        words.push({
          text: w.textContent.trim(),
          className: w.className,
          href: (w.tagName === 'A' ? w.href : null),
          dataset: Object.assign({}, w.dataset),
          parentClass: w.parentElement?.className
        });
      });
    } else {
      words.push({ text: el.textContent.trim(), tagName: el.tagName, className: el.className });
    }
  }

  // Also check the selects
  const selects = Array.from(document.querySelectorAll('select')).map(s => ({
    name: s.name,
    id: s.id,
    value: s.value,
    options: Array.from(s.options).map(o => ({ value: o.value, text: o.text, selected: o.selected }))
  }));

  return { words: words.slice(0, 50), totalWords: words.length, selects };
});

console.log("Selects:", JSON.stringify(syllableData.selects, null, 2));
console.log("Total word elements:", syllableData.totalWords);
console.log("First 30 words:", JSON.stringify(syllableData.words.slice(0, 30), null, 2));

