const tabId = 583778164;

const pageAnalysis = await browserjs(tabId, () => {
  // Let's inspect the sort select and see what happens when sort-by changes or what URL parameters exist
  const sortSelect = document.getElementById('rhymezone-search-sort-by-filter');

  // Also let's inspect all classes on the words under 3 syllables
  const h3s = Array.from(document.querySelectorAll('h3'));
  const targetH3 = h3s.find(h => h.textContent.trim().toLowerCase().includes('3 syllable'));

  let current = targetH3.nextElementSibling;
  const sections = [];
  while (current && current.tagName !== 'H3') {
    sections.push(current);
    current = current.nextElementSibling;
  }

  // Let's check classes, sub-headings, or lozenge colors
  const items = [];
  sections.forEach(sec => {
    const lozenges = sec.querySelectorAll('.lozenge, a');
    lozenges.forEach(l => {
      items.push({
        text: l.textContent.trim(),
        className: l.className,
        colorClass: Array.from(l.classList).find(c => c.startsWith('color-')),
        parentClasses: l.parentElement?.className,
        grandParentClasses: l.parentElement?.parentElement?.className
      });
    });
  });

  // Let's also check if there is an explanation of colors (a legend)
  const legend = Array.from(document.querySelectorAll('.legend, .frequency, .help, [class*="freq"], [class*="legend"]')).map(el => ({
    text: el.textContent.trim(),
    className: el.className
  }));

  return {
    url: window.location.href,
    sortSelectValue: sortSelect?.value,
    totalItems: items.length,
    sampleItems: items.slice(0, 40),
    colorClassesFound: Array.from(new Set(items.map(i => i.className))),
    legend
  };
});

console.log(JSON.stringify(pageAnalysis, null, 2));

