const tabId = 583778164;

const legendAndColors = await browserjs(tabId, () => {
  // Check the legend container and its text/styles
  const legendContainer = document.querySelector('.lozenge-legend') || document.querySelector('[class*="legend"]')?.parentElement;

  // Find all distinct color-* classes across the whole page
  const allLozenges = Array.from(document.querySelectorAll('.lozenge'));
  const colorCounts = {};
  allLozenges.forEach(l => {
    const col = Array.from(l.classList).find(c => c.startsWith('color-')) || 'no-color';
    colorCounts[col] = (colorCounts[col] || 0) + 1;
  });

  // Check CSS styles or computed styles of lozenge-legend-tile-* and color-*
  const getStyle = (selector) => {
    const el = document.querySelector(selector);
    if (!el) return null;
    const comp = window.getComputedStyle(el);
    return {
      backgroundColor: comp.backgroundColor,
      color: comp.color,
      opacity: comp.opacity
    };
  };

  return {
    legendHtml: legendContainer ? legendContainer.outerHTML : null,
    colorCounts,
    tileStyles: {
      tile1: getStyle('.lozenge-legend-tile-1'),
      tile2: getStyle('.lozenge-legend-tile-2'),
      tile3: getStyle('.lozenge-legend-tile-3'),
      tile4: getStyle('.lozenge-legend-tile-4'),
      color1: getStyle('.color-1'),
      color2: getStyle('.color-2'),
      color3: getStyle('.color-3'),
      color4: getStyle('.color-4'),
      color5: getStyle('.color-5'),
    }
  };
});

