const tabId = 583778164;

const dataInspection = await browserjs(tabId, () => {
  // Let's check script tags for any embedded json or rhymezone data
  const scripts = Array.from(document.querySelectorAll('script')).map(s => s.textContent || '');
  const jsonScripts = scripts.filter(s => s.includes('lozenge') || s.includes('rhyme') || s.includes('freq') || s.includes('aeronaut'));

  // Check window object for rhymezone or search data
  const windowKeys = Object.keys(window).filter(k => k.toLowerCase().includes('rhyme') || k.toLowerCase().includes('search') || k.toLowerCase().includes('word'));

  // Inspect the first few color-3 lozenge elements completely (all attributes and dataset)
  const h3s = Array.from(document.querySelectorAll('h3'));
  const targetH3 = h3s.find(h => h.textContent.trim().toLowerCase().includes('3 syllable'));
  let current = targetH3?.nextElementSibling;
  const sampleElements = [];
  while (current && current.tagName !== 'H3') {
    const loz = current.querySelector('.lozenge');
    if (loz) {
      sampleElements.push({
        html: loz.outerHTML,
        parentHtml: loz.parentElement?.outerHTML
      });
      if (sampleElements.length >= 3) break;
    }
    current = current.nextElementSibling;
  }

  return {
    matchingScriptsCount: jsonScripts.length,
    matchingScriptsSample: jsonScripts.map(s => s.slice(0, 300)),
    windowKeys,
    sampleElements
  };
});

console.log(JSON.stringify(dataInspection, null, 2));

