const tabId = 583778164;

const datamuseAll = await browserjs(tabId, async () => {
  const res = await fetch("https://api.datamuse.com/words?rel_rhy=thought&md=f&max=1000");
  const data = await res.json();

  // Filter for 3 syllables
  const threeSyllables = data.filter(item => item.numSyllables === 3);

  // Extract frequency f from tags
  const withFreq = threeSyllables.map(item => {
    const fTag = item.tags?.find(t => t.startsWith('f:'));
    const freq = fTag ? parseFloat(fTag.slice(2)) : 0;
    return {
      word: item.word,
      freq,
      score: item.score
    };
  });

  // Sort descending by frequency
  withFreq.sort((a, b) => b.freq - a.freq);

  return {
    total3Syllable: withFreq.length,
    top20ByFreq: withFreq.slice(0, 20),
    top20ByScore: [...withFreq].sort((a, b) => b.score - a.score).slice(0, 20)
  };
});

console.log(JSON.stringify(datamuseAll, null, 2));

