await tool.navigate({ tabId, url: "https://www.merriam-webster.com/rhymes/adv/thought" });
await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });

// Let's interact with the filters:
// 1. Uncheck near rhymes
// 2. Uncheck phrases
// 3. Sort by popularity descending
const filterRes = await browserjs(tabId, () => {
  const nearRhymes = document.getElementById("rhymezone-search-near-rhymes-filter");
  const phrases = document.getElementById("rhymezone-search-phrase-type");

  if (nearRhymes && nearRhymes.checked) {
    nearRhymes.click();
  }
  if (phrases && phrases.checked) {
    phrases.click();
  }

  // Sort by popularity
  const popHeader = Array.from(document.querySelectorAll('.sortable-col')).find(el => el.getAttribute('data-sort-type') === 'popularity');
  if (popHeader) {
    popHeader.click(); // first click: asc or desc
    if (!popHeader.classList.contains('sort-desc')) {
      popHeader.click(); // ensure desc
    }
  }

  // Get table rows
  const rows = Array.from(document.querySelectorAll('.rhymes-table tbody tr')).map(tr => {
    return Array.from(tr.querySelectorAll('td')).map(td => td.textContent.trim());
  });

  return {
    nearRhymesChecked: nearRhymes?.checked,
    phrasesChecked: phrases?.checked,
    popHeaderClass: popHeader?.className,
    rowCount: rows.length,
    rows: rows.slice(0, 25)
  };
});

